'use client';

import React, { useState } from 'react';
import { Card, Button } from '@/components/ui/base';
import { Plus, TrendingUp, TrendingDown, Info, Brain, LineChart, Mail } from 'lucide-react';
import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, 
  Cell, PieChart, Pie, Legend, AreaChart, Area 
} from 'recharts';
import { AddTransactionModal } from '@/components/ui/add-transaction-modal';
import { useTransactions } from '@/lib/transaction-context';

export default function DashboardPage() {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const { transactions, stats, userProfile } = useTransactions();
  const [aiInsight, setAiInsight] = useState<{title: string, analysis: string, tip: string, sentiment: string} | null>(null);
  const [isSendingEmail, setIsSendingEmail] = useState(false);

  React.useEffect(() => {
     async function fetchInsight() {
        try {
            const res = await fetch('/api/analysis', {
                method: 'POST',
                body: JSON.stringify({
                    transactions,
                    totalIncome: stats.totalIncome,
                    totalExpense: stats.totalExpense
                })
            });
            if (res.ok) {
                const data = await res.json();
                setAiInsight(data);
            }
        } catch (e) {
            console.error("Failed to fetch AI insight");
        }
     }
     
     if (transactions.length > 0) {
         fetchInsight();
     }
  }, [transactions, stats]);

  // Dynamic Forecast Data
  const forecastData = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    if (expenses.length === 0) {
       return [
        { name: 'Week 1', actual: 0, predicted: 200 },
        { name: 'Week 2', actual: 0, predicted: 250 },
        { name: 'Week 3', actual: 0, predicted: 230 },
        { name: 'Week 4', actual: 0, predicted: 280 },
        { name: 'Next Week', actual: null, predicted: 300 },
      ];
    }
    
    // Sort transactions by date
    // Simple simulation: We divide the total expenses roughly into "Past weeks" to simulate trend
    // In a real app, this would be actual time-series aggregation
    const totalExp = stats.totalExpense;
    const avg = totalExp / 4; 
    
    // Add some random variance to make it look "predicted"
    return [
      { name: 'Week 1', actual: avg * 0.85, predicted: avg * 0.9 },
      { name: 'Week 2', actual: avg * 1.1, predicted: avg * 1.05 },
      { name: 'Week 3', actual: avg * 0.95, predicted: avg },
      { name: 'Week 4', actual: avg * 1.2, predicted: avg * 1.15 },
      { name: 'Next Week', actual: null, predicted: avg * 1.1 }, // Forecast
    ];
  }, [transactions, stats.totalExpense]);

  // Key Insight Generation
  const insight = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    if (expenses.length === 0) return { category: 'None', amount: 0 };
    
    const catTotals: Record<string, number> = {};
    expenses.forEach(t => {
      catTotals[t.category] = (catTotals[t.category] || 0) + t.amount;
    });
    
    const topCategory = Object.keys(catTotals).reduce((a, b) => catTotals[a] > catTotals[b] ? a : b);
    return { category: topCategory, amount: catTotals[topCategory] };
  }, [transactions]);

  // Process data for charts
  const chartData = React.useMemo(() => {
    const last7Days = Array.from({ length: 7 }, (_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - (6 - i));
      return d.toISOString().split('T')[0];
    });

    return last7Days.map(date => {
      const dayTransactions = transactions.filter(t => t.date === date);
      const income = dayTransactions.filter(t => t.type === 'Income').reduce((acc, t) => acc + t.amount, 0);
      const expense = dayTransactions.filter(t => t.type === 'Expense').reduce((acc, t) => acc + t.amount, 0);
      return {
        name: new Date(date).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }),
        income,
        expense
      };
    });
  }, [transactions]);

  const pieData = React.useMemo(() => {
    const expenses = transactions.filter(t => t.type === 'Expense');
    const categories = Array.from(new Set(expenses.map(t => t.category)));
    const colors = ['#f97316', '#10b981', '#0f172a', '#ef4444', '#8b5cf6', '#f59e0b'];
    
    return categories.map((category, index) => ({
      name: category,
      value: expenses.filter(t => t.category === category).reduce((acc, t) => acc + t.amount, 0),
      color: colors[index % colors.length]
    })).sort((a, b) => b.value - a.value).slice(0, 5);
  }, [transactions]);

  const incomeCount = transactions.filter(t => t.type === 'Income').length;
  const expenseCount = transactions.filter(t => t.type === 'Expense').length;

  const handleEmailReport = async () => {
    const userEmail = userProfile?.email;
    
    if (!userEmail) {
        alert("Please set your email in Settings > Account to receive reports.");
        return;
    }

    setIsSendingEmail(true);

    // Construct the email content
    const subject = "Monthly Financial Scan Report - AI Finance";
    const userName = userProfile?.name ? ` ${userProfile.name}` : '';
    
    // Create a simple HTML version
    const htmlContent = `
      <div style="font-family: sans-serif; color: #333;">
        <h2>Hello${userName},</h2>
        <p>Here is your generated financial report for the current period.</p>
        
        <div style="background: #f3f4f6; padding: 20px; border-radius: 8px; margin: 20px 0;">
          <h3 style="margin-top: 0; border-bottom: 2px solid #ccc; padding-bottom: 10px;">FINANCIAL SUMMARY</h3>
          <p><strong>Total Income:</strong> ₹${stats.totalIncome.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          <p><strong>Total Expenses:</strong> ₹${stats.totalExpense.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
          <p><strong>Net Balance:</strong> ₹${stats.netProfit.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
        </div>

        <div style="border: 1px solid #e5e7eb; padding: 20px; border-radius: 8px; margin: 20px 0;">
            <h3 style="margin-top: 0; color: #10b981;">AI ANALYSIS</h3>
            <p><strong>Title:</strong> ${aiInsight?.title || 'N/A'}</p>
            <p><strong>Insight:</strong> ${aiInsight?.analysis || 'No analysis available.'}</p>
            <p><strong>Sentiment:</strong> ${aiInsight?.sentiment?.toUpperCase() || 'NEUTRAL'}</p>
        </div>

        <div style="background: #ecfdf5; padding: 20px; border-radius: 8px; margin: 20px 0; border-left: 4px solid #10b981;">
            <h3 style="margin-top: 0; color: #065f46;">RECOMMENDATION</h3>
            <p>${aiInsight?.tip || 'Track more transactions to get better insights.'}</p>
        </div>
        
        <p style="color: #6b7280; font-size: 0.875rem; margin-top: 40px;">Generated by AI Finance App</p>
      </div>
    `;

    try {
        const res = await fetch('/api/send-report', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                to: userEmail,
                subject: subject,
                html: htmlContent
            })
        });

        const data = await res.json();

        if (res.ok && data.success) {
            alert(data.message || "Email sent successfully!");
        } else {
            console.error("Email send failed:", data);
            alert(`Failed to send email: ${data.details || data.error || "Unknown error"}`);
        }
    } catch (error) {
        console.error("Error sending report:", error);
        alert("An error occurred while sending the email.");
    } finally {
        setIsSendingEmail(false);
    }
  };

  return (
    <div className="space-y-8">
      <AddTransactionModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      
      {/* Header Section */}
      <div className="bg-[#111827] text-white p-8 rounded-2xl shadow-lg -mt-4">
        {aiInsight && (
            <div className={`mb-6 p-4 rounded-xl border-l-4 ${aiInsight.sentiment === 'positive' ? 'bg-green-900/30 border-green-500' : aiInsight.sentiment === 'negative' ? 'bg-red-900/30 border-red-500' : 'bg-blue-900/30 border-blue-500'}`}>
                <div className="flex items-center gap-2 mb-2">
                    <Brain className="text-purple-400" size={20} />
                    <h3 className="font-bold text-lg">{aiInsight.title}</h3>
                </div>
                <p className="text-gray-300 text-base mb-2">{aiInsight.analysis}</p>
                <div className="flex gap-2 items-center bg-[#1f2937] p-2 rounded-lg w-fit mt-2">
                    <Info size={16} className="text-blue-400" />
                    <span className="text-sm font-medium text-blue-300">Tip: {aiInsight.tip}</span>
                </div>
            </div>
        )}

        <div className="flex justify-between items-start mb-8">
          <div>
            <h1 className="text-4xl font-bold mb-2">Welcome back, TechWithEmma</h1>
            <p className="text-gray-400 text-lg">This is your overview report for the selected period</p>
          </div>
          <div className="flex gap-4 items-center">
            <select className="bg-[#1f2937] border-none text-white rounded-md px-4 py-2 text-base focus:ring-2 focus:ring-green-500">
              <option>Last 30 Days</option>
              <option>Last 7 Days</option>
              <option>This Month</option>
            </select>
            <Button 
              variant="outline" 
              className="bg-[#1f2937] border-0 text-white hover:bg-gray-700 hidden md:flex text-base disabled:opacity-50 gap-2" 
              onClick={handleEmailReport}
              disabled={isSendingEmail}
            >
              <Mail className="h-4 w-4" /> 
              {isSendingEmail ? "Sending..." : "Email Report"}
            </Button>
            <Button variant="primary" className="gap-2 text-base" onClick={() => setIsModalOpen(true)}>
              <Plus size={20} /> Add Transaction
            </Button>
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
          <div className="bg-[#1f2937] p-8 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-blue-400 text-base font-medium">Available Balance</h3>
            </div>
            <p className="text-4xl font-bold mb-2">₹{stats.netProfit.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
            <p className="text-green-400 text-sm flex items-center gap-1">
              <TrendingUp size={14} /> +38.8% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-8 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-base font-medium">Total Income</h3>
            </div>
            <p className="text-4xl font-bold mb-2">₹{stats.totalIncome.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
            <p className="text-green-400 text-sm flex items-center gap-1">
              <TrendingUp size={14} /> +25.0% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-8 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-base font-medium">Total Expenses</h3>
            </div>
            <p className="text-4xl font-bold mb-2">-₹{stats.totalExpense.toLocaleString('en-IN', { minimumFractionDigits: 2 })}</p>
            <p className="text-red-400 text-sm flex items-center gap-1">
              <TrendingDown size={14} /> -21.6% <span className="text-gray-500">for Past 30 Days</span>
            </p>
          </div>

          <div className="bg-[#1f2937] p-8 rounded-xl">
            <div className="flex justify-between items-start mb-2">
              <h3 className="text-gray-400 text-base font-medium">Savings Rate</h3>
            </div>
            <p className="text-4xl font-bold mb-2">
              {stats.totalIncome > 0 ? ((stats.netProfit / stats.totalIncome) * 100).toFixed(1) : 0}%
            </p>
            <p className="text-red-400 text-sm flex items-center gap-1">
              <TrendingDown size={14} /> High Spend <span className="text-gray-500">• {stats.totalIncome > 0 ? ((stats.totalExpense / stats.totalIncome) * 100).toFixed(0) : 0}% spent</span>
            </p>
          </div>
        </div>
      </div>

      {/* Recent Transactions List */}
      <Card className="p-8">
        <div className="flex justify-between items-center mb-6">
          <h3 className="text-xl font-bold text-gray-900">Recent Transactions</h3>
          <a href="/transactions" className="text-base text-green-500 hover:text-green-600 font-medium">View All</a>
        </div>
        <div className="space-y-4">
          {transactions.slice(0, 5).map((t) => (
            <div key={t.id} className="flex items-center justify-between p-6 bg-gray-50 rounded-lg hover:bg-gray-100 transition-colors">
              <div className="flex items-center gap-4">
                <div className={`p-4 rounded-full ${t.type === 'Income' ? 'bg-green-100 text-green-600' : 'bg-red-100 text-red-600'}`}>
                  {t.type === 'Income' ? <TrendingUp size={24} /> : <TrendingDown size={24} />}
                </div>
                <div>
                  <p className="font-semibold text-lg text-gray-900">{t.description}</p>
                  <p className="text-sm text-gray-500">{t.category} • {new Date(t.date).toLocaleDateString()}</p>
                </div>
              </div>
              <div className="text-right">
                <p className={`font-bold text-lg ${t.type === 'Income' ? 'text-green-600' : 'text-gray-900'}`}>
                  {t.type === 'Income' ? '+' : '-'}₹{t.amount.toLocaleString('en-IN', { minimumFractionDigits: 2 })}
                </p>
                <p className="text-sm text-gray-500">{t.paymentMethod}</p>
              </div>
            </div>
          ))}
          {transactions.length === 0 && (
            <p className="text-center text-gray-500 py-8">No transactions yet. Add one to get started!</p>
          )}
        </div>
      </Card>
    </div>
  );
}
